import { DeskError } from './errors';
import { remainingUnits } from './quantity';
import type { AvailabilityQuery, AvailabilityQuote, DeskSnapshot } from './types';

/** 从快照计算借用台展示与提交使用的余量，不修改快照。 */
export function availabilityFor(snapshot: DeskSnapshot, query: AvailabilityQuery): AvailabilityQuote {
  const stock = snapshot.stocks.find((row) => row.siteId === query.siteId && row.kitId === query.kitId);
  if (!stock) throw new DeskError('UNKNOWN_STOCK');

  const occupied = snapshot.loans
    .filter((loan) => loan.kitId === query.kitId && loan.status !== 'CANCELLED')
    .reduce((sum, loan) => sum + loan.quantity, 0);

  return {
    siteId: query.siteId,
    kitId: query.kitId,
    total: stock.total,
    occupied,
    available: remainingUnits(stock.total, occupied),
  };
}

export type DeskErrorCode = 'INVALID_QUANTITY' | 'UNKNOWN_STOCK' | 'LOAN_NOT_FOUND'
  | 'READ_ONLY_LOAN' | 'INSUFFICIENT_STOCK';

const messages: Record<DeskErrorCode, string> = {
  INVALID_QUANTITY: '数量必须为正整数',
  UNKNOWN_STOCK: '该地点未配置此器材库存',
  LOAN_NOT_FOUND: '借用单不存在',
  READ_ONLY_LOAN: '只有已确认借用单可以修改',
  INSUFFICIENT_STOCK: '可借数量不足，请按最新余量调整',
};

export class DeskError extends Error {
  readonly code: DeskErrorCode;

  constructor(code: DeskErrorCode) {
    super(messages[code]);
    this.name = 'DeskError';
    this.code = code;
  }
}

export function readableError(error: unknown): string {
  return error instanceof Error ? error.message : '操作未完成，请重新检查输入';
}

import { DeskError } from './errors';

/** 对业务数量做集中检查，表单和直接调用都经这里进入。 */
export function assertRequestedQuantity(quantity: number): void {
  if (!Number.isFinite(quantity) || quantity < 1) {
    throw new DeskError('INVALID_QUANTITY');
  }
}

/** 表单空值保留为 0，由业务层给出已有错误信息。 */
export function quantityFromInput(value: string): number {
  return value.trim() === '' ? 0 : Number(value);
}

export function remainingUnits(total: number, occupied: number): number {
  return Math.max(0, total - occupied);
}

export type SiteId = 'harbor' | 'hill';
export type LoanStatus = 'DRAFT' | 'CONFIRMED' | 'COLLECTED' | 'RETURNED' | 'CANCELLED';

export interface Site {
  id: SiteId;
  name: string;
}

export interface Kit {
  id: string;
  name: string;
  depositPerUnit: number;
  description: string;
}

export interface StockRow {
  siteId: SiteId;
  kitId: string;
  total: number;
}

export interface Loan {
  id: string;
  siteId: SiteId;
  kitId: string;
  quantity: number;
  status: LoanStatus;
  purpose: string;
  revision: number;
}

export interface DeskSnapshot {
  sites: Site[];
  kits: Kit[];
  stocks: StockRow[];
  loans: Loan[];
}

export interface AvailabilityQuery {
  siteId: SiteId;
  kitId: string;
  excludeLoanId?: string;
}

export interface AvailabilityQuote {
  siteId: SiteId;
  kitId: string;
  total: number;
  occupied: number;
  available: number;
}

export interface NewLoanCommand {
  siteId: SiteId;
  kitId: string;
  quantity: number;
  purpose: string;
}

export interface EditLoanCommand {
  loanId: string;
  quantity: number;
  purpose: string;
}

export interface LoanRepository {
  snapshot(): DeskSnapshot;
  insert(command: NewLoanCommand): Loan;
  update(loanId: string, quantity: number, purpose: string): Loan;
}

export interface LoanDesk {
  snapshot(): DeskSnapshot;
  getLoan(loanId: string): Loan;
  quoteNew(siteId: SiteId, kitId: string): AvailabilityQuote;
  quoteEdit(loanId: string): AvailabilityQuote;
  createLoan(command: NewLoanCommand): Loan;
  updateLoan(command: EditLoanCommand): Loan;
}

declare module '*.vue' {
  import type { DefineComponent } from 'vue';
  const component: DefineComponent<Record<string, unknown>, Record<string, unknown>, unknown>;
  export default component;
}

export interface Signup { id: string; eventId: string; seats: number; state: 'BOOKED' | 'WAITING' | 'CANCELLED'; }

/** 活动报名采用独立名额口径：候补不占正式席位。 */
export function availabilityFor(capacity: number, eventId: string, signups: Signup[]): number {
  const used = signups.filter((row) => row.eventId === eventId && row.state === 'BOOKED')
    .reduce((sum, row) => sum + row.seats, 0);
  return Math.max(0, capacity - used);
}

import { availabilityFor, type Signup } from './availability';

export interface EventDefinition { id: string; title: string; capacity: number; }

export function previewSignup(event: EventDefinition, seats: number, signups: Signup[]) {
  if (!Number.isSafeInteger(seats) || seats < 1) return { allowed: false, reason: '席位数量无效', remaining: 0 };
  const remaining = availabilityFor(event.capacity, event.id, signups);
  return { allowed: seats <= remaining, reason: seats <= remaining ? '' : '可进入候补名单', remaining };
}

export function eventCountSummary(eventId: string, signups: Signup[]) {
  const selected = signups.filter((row) => row.eventId === eventId);
  return {
    booked: selected.filter((row) => row.state === 'BOOKED').reduce((sum, row) => sum + row.seats, 0),
    waiting: selected.filter((row) => row.state === 'WAITING').reduce((sum, row) => sum + row.seats, 0),
  };
}

export interface LegacyBorrowRow { deviceCode: string; pieces: number; closed: boolean; }

/** 退役工作台的旧口径，只供旧记录回看；没有地点维度。 */
export function availabilityFor(total: number, deviceCode: string, rows: LegacyBorrowRow[]): number {
  return Math.max(0, total - rows.filter((row) => row.deviceCode === deviceCode && !row.closed)
    .reduce((sum, row) => sum + row.pieces, 0));
}

export function legacySummary(rows: LegacyBorrowRow[]): string {
  const open = rows.filter((row) => !row.closed);
  return `旧台账未结 ${open.length} 单，共 ${open.reduce((sum, row) => sum + row.pieces, 0)} 件`;
}

